mapper.select:
select m.id, m.category, m.general, m.range_min, m.range_max, m.step_high, m.step_higher, m.step_highest,
m.auto_flag, a.name assetName, md.name deskStr, o.title orgName, a.ip assetIp, bt.name serviceTypeStr,
o.id orgId, bt.id serviceTypeId, md.CODE assetDesk, a.id assetId
from threshold_manage m
left join asset a on a.id = m.asset_id
left join asset_mode md on m.asset_desk = md.code
left join sys_org o on m.org_id = o.id
left join businessservice_service_type bt on m.service_type_id = bt.id
where a.is_del = 1

    and m.org_id in

        #{id}



    and m.org_id = #{orgId}


    and m.asset_desk = #{assetDesk}


    and m.auto_flag = #{autoFlag}


    and m.category = #{category}


    and m.service_type_id = #{serviceTypeId}


    and a.name like concat(concat('%', #{assetName}), '%')


    and a.ip = #{assetIp} or a.ip2 = #{assetIp}

order by m.modify_time desc

select m.category, m.org_id, m.asset_desk, m.general, m.range_min, m.range_max, m.step_high, m.step_higher, m.step_highest, m.org_id, m.auto_flag, o.title orgName, md.name deskStr from THRESHOLD_MANAGE m left join asset a on a.id = m.asset_id left join asset_mode md on m.asset_desk = md.code left join sys_org o on m.org_id = o.id where m.auto_flag = 1 and a.is_del = 1
and m.org_id in
#{id}
and m.org_id = #{orgId}
and m.category = #{category}
and m.asset_desk = #{assetDesk}
group by category, m.org_id, m.asset_desk, m.general, m.range_min, m.range_max, m.step_high, m.step_higher, m.step_highest, m.org_id, md.name, o.title, m.auto_flag order by m.org_id
